head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[tabControl > P > keepDisabledTab]<br/>컴포넌트의 비활성화(disabled)를 해제할때 Tab 페이지의 비활성화(disabled) 상태를 별도 처리할지 설정합니다.",
    "validation" : [
        "미설정 또는 false 설정 시 setDisabled(false) 실행 시 전체 Tab 페이지의 비활성화(disabled)를 해제합니다.",
        "true 설정 시 Tab 페이지의 비활성화(disabled) 상태를 보관했다가 setDisabled(true) 실행 시 이전 상태로 복원합니다.",
        "true 설정 시 Tab 페이지의 이전 상태가 비활성화(disabled)였으면 비활성화(disabled) 상태를 유지합니다.",
    ]
}



scwin.onpageload = function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // comp 초기 생성
    scwin.comp_init();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// comp 생성
scwin.comp_init = async function () {
    // 기존 target 있으면 삭제
    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    // 조건 설정   
    let properties = {
        keepDisabledTab: con_keepDisabledTab.getText(),
    };

    let cList = $c.gcm.createCList(properties);          

    let grp_comp = $c.gcm.getTestGroup();    
    let strTarget = '';
    let strNameSpace = $c.gcm.getNameSpace();

    strTarget += '<w2:tabControl ' + strNameSpace + ' ' + cList + ' id="" style="width:500px;height:200px;">';
    strTarget += '<w2:tabs disabled="false" style="height:40px;" id="tabs1" label="Tabs1"></w2:tabs>';
    strTarget += '<w2:tabs disabled="true" style="height:40px" id="tabs2" label="Tabs2"></w2:tabs>';
    strTarget += '<w2:tabs disabled="true" style="height:40px" id="tabs3" label="Tabs3"></w2:tabs>';
    strTarget += '<w2:content style="height:160px;" id="content1">';
    strTarget += '<w2:button style="width:80px; width:130px; height:50px;" id="content1_child" label="content1_child"></w2:button>';
    strTarget += '</w2:content>';
    strTarget += '<w2:content style="height:160px" id="content2">';
    strTarget += '<xf:input id="content2_child" style="width:144px; height:21px; " initValue="content2_child"></xf:input>';
    strTarget += '</w2:content>';
    strTarget += '<w2:content style="height:160px" id="content3">';    
    strTarget += '<w2:textbox id="content3_child" label="content3_child" style="width:200px; height:50px; background-color:var(--ws-gray-300);"></w2:textbox>';
    strTarget += '</w2:content>';
    strTarget += '</w2:tabControl>';

    // target 생성
    scwin.target1 = await $p.dynamicCreate(
        "target1",
        "tabControl",
        strTarget,
        grp_comp
    );
}



scwin.btn_getDisabled_onclick = function (e) {   
    const tabIndexes = [0, 1, 2];

    tabIndexes.forEach(index => {
        let tab = document.querySelector(`li[id*=target1_tab_tabs${index + 1}]`);
        wf_body_bottom.getObj("scwin").setReturnValue(`tabs${index + 1} className : ${tab.className}`);
    });
};



scwin.btn_setDisabled_onclick = function (e) {
	target1.setDisabled(false);

    scwin.btn_getDisabled_onclick();
};
